func TestFinalizeAllTurnCheckpointsStopsAtTotalBudget(t *testing.T) {
	workDir := setupGitRepo(t)
	t.Chdir(workDir)
	paths.ClearWorktreeRootCache()

	require.NoError(t, os.MkdirAll(filepath.Join(workDir, ".entire"), 0o755))
	require.NoError(t, os.WriteFile(
		filepath.Join(workDir, ".entire", "settings.json"),
		[]byte(`{"enabled":true,"checkpoints":{"primary":{"type":"git-refs"}}}`),
		0o644,
	))

	repo, err := git.PlainOpen(workDir)
	require.NoError(t, err)
	t.Cleanup(func() { require.NoError(t, repo.Close()) })

	sessionID := "slow-finalize"
	checkpointIDs := []id.CheckpointID{
		id.MustCheckpointID("01ARZ3NDEKTSV4RRFFQ69G5FAV"),
		id.MustCheckpointID("01ARZ3NDEKTSV4RRFFQ69G5FAW"),
		id.MustCheckpointID("01ARZ3NDEKTSV4RRFFQ69G5FAX"),
	}
	stores, err := checkpoint.Open(context.Background(), repo, checkpoint.OpenOptions{})
	require.NoError(t, err)
	refHashes := make(map[plumbing.ReferenceName]plumbing.Hash, len(checkpointIDs))
	for _, checkpointID := range checkpointIDs {
		require.NoError(t, stores.Persistent.Write(context.Background(), checkpoint.Session{
			CheckpointID: checkpointID,
			SessionID:    sessionID,
			Strategy:     StrategyNameManualCommit,
			Transcript:   redact.AlreadyRedacted([]byte("provisional transcript\n")),
			AuthorName:   "Test",
			AuthorEmail:  "test@example.com",
			Agent:        "Claude Code",
		}))
		refName, refErr := checkpoint.RefName(checkpointID)
		require.NoError(t, refErr)
		ref, refErr := repo.Reference(refName, true)
		require.NoError(t, refErr)
		refHashes[refName] = ref.Hash()
		require.NoError(t, repo.Storer.RemoveReference(refName))
	}

	transcriptPath := filepath.Join(workDir, ".entire", "metadata", sessionID, paths.TranscriptFileName)
	require.NoError(t, os.MkdirAll(filepath.Dir(transcriptPath), 0o755))
	require.NoError(t, os.WriteFile(transcriptPath, []byte(testTranscriptPromptResponse), 0o644))
	state := &SessionState{
		SessionID:         sessionID,
		AgentType:         "Claude Code",
		TranscriptPath:    transcriptPath,
		TurnCheckpointIDs: []string{checkpointIDs[0].String(), checkpointIDs[1].String(), checkpointIDs[2].String()},
	}

	s := NewManualCommitStrategy()
	s.turnCheckpointFinalizeBudget = 25 * time.Millisecond
	fetchCalls := 0
	s.checkpointRefFetcher = func(ctx context.Context, refName plumbing.ReferenceName) error {
		fetchCalls++
		timer := time.NewTimer(15 * time.Millisecond)
		defer timer.Stop()
		select {
		case <-timer.C:
			return repo.Storer.SetReference(plumbing.NewHashReference(refName, refHashes[refName]))
		case <-ctx.Done():
			return ctx.Err()
		}
	}

	started := time.Now()
	errCount := s.finalizeAllTurnCheckpoints(context.Background(), state)
	elapsed := time.Since(started)

	finalized := 0
	for _, checkpointID := range checkpointIDs {
		refName, refErr := checkpoint.RefName(checkpointID)
		require.NoError(t, refErr)
		if _, refErr = repo.Reference(refName, true); refErr == nil {
			finalized++
		}
	}

	require.Less(t, elapsed, 40*time.Millisecond)
	require.Less(t, finalized, len(checkpointIDs), "the pass must stop before every slow fetch completes")
	require.Equal(t, len(checkpointIDs)-finalized, errCount, "every provisional checkpoint must count as an error")
	require.LessOrEqual(t, fetchCalls, 2, "no checkpoint fetch may start after the total budget expires")
	require.Empty(t, state.TurnCheckpointIDs, "a best-effort pass has no durable retry path")
	require.NotNil(t, state.CaptureDegradedAt, "the incomplete finalize must be visible through `entire status`")
}

	// Read full transcript from live transcript file, re-resolving the path if the
	// agent relocated it mid-session (e.g., Cursor CLI flat → nested layout change).
	if state.TranscriptPath == "" {
		logging.Warn(logCtx, "finalize: no transcript path, skipping",
			slog.String("session_id", state.SessionID),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	transcriptPath, resolveErr := resolveTranscriptPath(state)
	if resolveErr != nil {
		logging.Warn(logCtx, "finalize: transcript path resolution failed, skipping",
			slog.String("session_id", state.SessionID),
			slog.Any("error", resolveErr),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	fullTranscript, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
	if err != nil || len(fullTranscript) == 0 {
		msg := "finalize: empty transcript, skipping"
		if err != nil {
			msg = "finalize: failed to read transcript, skipping"
		}
		logging.Warn(logCtx, msg,
			slog.String("session_id", state.SessionID),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Any("error", err),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	// Open repository (needed for shadow branch prompt reading and checkpoint store)
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open repository",
			slog.String("error", err.Error()),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}
	defer repo.Close()
	policy, err := readLocalCheckpointPolicy(logCtx, repo)
	if err != nil {
		warnOrLogCheckpointPolicyReadFailure(logCtx, err)
		state.TurnCheckpointIDs = nil
		return 1
	}
	if !checkpointpolicy.CanSatisfyPolicy(policy) {
		warnIfCheckpointPolicyNeedsUpgrade(logCtx, policy)
		state.TurnCheckpointIDs = nil
		return 1
	}

	prompts := readPromptsFromShadowBranch(ctx, repo, state)
	if len(prompts) == 0 {
		prompts = readPromptsFromFilesystem(ctx, state.SessionID)
	}

	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; ExtractSkillEvents handles nil
	// Persist newly extracted events into state (the caller's MutateSessionState
	// saves them); telemetry for them is emitted by the lifecycle turn-end
	// handler, which snapshots state.SkillEvents growth around HandleTurnEnd.
	_, skillEvents := persistNewSkillEvents(state, agent.ExtractSkillEvents(ctx, ag, fullTranscript, 0))

	// Sanitize before externalizing and redacting, matching CondenseSession's
	// sanitize -> externalize -> redact order. Skill events above are extracted from
	// the pre-sanitization bytes because they are session telemetry rather than
	// stored transcript content.
	fullTranscript = agent.SanitizeTranscriptForStorage(ag, fullTranscript)

	// Redact secrets before writing. Checkpoint store methods require
	// pre-redacted in-memory transcript content from callers. The live
	// transcript on disk is still treated as raw/untrusted input, so redact it
	// here before anything is persisted to the metadata branch.
	//
	// On failure: drop the transcript but continue writing checkpoint metadata
	// (attribution, files touched, prompts). Hooks run without user interaction
	// so there is no retry path — preserving partial metadata is better than
	// losing everything. Persisting an unredacted transcript would be worse.
	// Run the regex-only pipeline over the transcript — OPF runs later in
	// the pre-push rewrite path, which re-redacts these regex-only blobs
	// and produces OPF-applied (9-layer) commits before the push goes out.
	// Externalize inline images BEFORE redaction, mirroring CondenseSession, so the
	// finalized (authoritative, full-session) transcript keeps its placeholders and
	// matching assets instead of re-inlining what condensation lifted out. Opt-in;
	// a no-codec agent or a transcript with no images is a no-op.
	var finalizeAssets []checkpoint.TranscriptAsset
	// Whether externalization actually RAN at finalize. When it did not (flag
	// off here even though it may have been on at condensation — e.g. an
	// ENTIRE_EXTERNALIZE_IMAGES env override not inherited by the hook
	// process, or settings toggled mid-session), an empty finalizeAssets means
	// "extraction didn't run", NOT "the transcript has no images" — clearing
	// the previously-stored assets would permanently lose them (the re-inlined
	// base64 is destroyed by redaction below).
	externalizationRan := false
	if settings.IsImageExternalizationEnabled(ctx) {
		rewritten, assets, exErr := extractSessionImages(state.AgentType, fullTranscript)
		if exErr != nil {
			logging.Warn(logCtx, "finalize: image externalization failed; leaving transcript inline",
				slog.String("session_id", state.SessionID),
				slog.String("error", exErr.Error()),
			)
		} else {
			fullTranscript = rewritten
			finalizeAssets = assets
			externalizationRan = true
		}
	}
	// Re-capture sidecar images (e.g. Cursor's SQLite store) so a finalize that
	// rewrites the transcript re-writes them too. When the full transcript differs
	// from the stored (mid-turn) one, writeAssets clears the whole assets/ folder
	// and re-writes only these assets — omitting the sidecar images here would drop
	// what CondenseSession captured. Content-hash names make this idempotent with
	// condensation's write; when the transcript is unchanged, writeAssets is not
	// called and condensation's assets are left intact.
	finalizeAssets = append(finalizeAssets, sidecarSessionImages(ctx, logCtx, ag, state)...)
	// Sidecar capture is best-effort: a transient miss here (sqlite3 locked/timed
	// out) yields no assets. For a sidecar-capable agent, preserve the assets a
	// prior condensation stored rather than letting an empty set clear them.
	_, sidecarCapable := agent.AsSidecarImageProvider(ag)

	redactedTranscript, redactOK := redactFinalizedTranscript(logCtx, repo, state.SessionID, fullTranscript)
	if !redactOK {
		return 1
	}

	// Post-commit emits regex-only blobs; the writer joins + redacts
	// via checkpoint.redactedJoinedPrompts. OPF runs later, once per
	// push, in the pre-push rewrite path.
	// The hook store envelope (see hookCheckpointStoreOptions): the transcript
	// finalize targets existing checkpoints whose refs — and, on a partial
	// clone, whose blobs — may live only on the remote (resumed/adopted
	// multi-machine sessions). This loops over every checkpoint of the turn
	// against one store, so both fetch paths need their own memo or a dead
	// network costs the budget N times: gitRefsStore.fetchFailure covers refs,
	// and hookBlobFetcher memoizes an exhausted blob fetch. The context enclosing
	// this finalize pass bounds slow successes, which neither memo can detect.
	stores, err := checkpoint.Open(ctx, repo, s.hookCheckpointStoreOptions(ctx))
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open checkpoint store",
			slog.String("error", err.Error()),
		)
		return 1 // Count as error - all checkpoints will be skipped
	}
	store := stores.Persistent

	precomputed := precomputeTranscriptBlobsForFinalize(logCtx, repo, redactedTranscript, state)
	updateOpts := checkpoint.UpdateOptions{
		SessionID:               state.SessionID,
		Transcript:              redactedTranscript,
		Assets:                  finalizeAssets,
		PreserveAssetsWhenEmpty: sidecarCapable || !externalizationRan,
		Prompts:                 prompts,
		Agent:                   state.AgentType,
		SkillEvents:             skillEvents,
		PrecomputedBlobs:        precomputed,
	}
	errCount += finalizeTurnCheckpointWrites(ctx, logCtx, store, state, updateOpts)

	// Clear turn checkpoint IDs. Do NOT update CheckpointTranscriptStart here — it was
	// already set correctly by PostCommit: condenseAndUpdateState sets it to the total
	// transcript lines when condensing, and carryForwardToNewShadowBranch resets it to 0
	// when carry-forward is active. Overwriting here would break carry-forward by making
	// sessionHasNewContent think the transcript is fully consumed (no growth).
	state.TurnCheckpointIDs = nil

	return errCount
}

func turnCheckpointFinalizeBudgetForAgent(agentType types.AgentType) time.Duration {
	// Only hosts with verified headroom get the longer budget; the fallback must
	// fit Pi's 10-second subprocess limit so new agents fail safe.
	switch agentType {
	case agent.AgentTypeClaudeCode, agent.AgentTypeCodex:
		return standardTurnCheckpointFinalizeBudget
	default:
		return constrainedTurnCheckpointFinalizeBudget
	}
}

func finalizeTurnCheckpointWrites(
	ctx context.Context,
	logCtx context.Context,
	store checkpoint.PersistentStore,
	state *SessionState,
	updateOpts checkpoint.UpdateOptions,
) int {
	errCount := 0
	for checkpointIndex, cpIDStr := range state.TurnCheckpointIDs {
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			remaining := len(state.TurnCheckpointIDs) - checkpointIndex
			errCount += remaining
			recordTurnCheckpointFinalizeDegraded(logCtx, state, remaining)
			break
		}

		cpID, err := id.NewCheckpointID(cpIDStr)
		if err != nil {
			logging.Warn(logCtx, "finalize: invalid checkpoint ID, skipping",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", err.Error()),
			)
			errCount++
			continue
		}

		updateOpts.CheckpointID = cpID
		if err := store.Write(ctx, checkpoint.SessionTranscript(updateOpts)); err != nil {
			logging.Warn(logCtx, "finalize: failed to update checkpoint",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", err.Error()),
			)
			errCount++
			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
				remaining := len(state.TurnCheckpointIDs) - checkpointIndex - 1
				errCount += remaining
				recordTurnCheckpointFinalizeDegraded(logCtx, state, remaining+1)
				break
			}
			continue
		}

		logging.Info(logCtx, "finalize: checkpoint updated with full transcript",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("session_id", state.SessionID),
		)
	}
	return errCount
}

func recordTurnCheckpointFinalizeDegraded(logCtx context.Context, state *SessionState, unfinalized int) {
	now := time.Now().UTC()
	state.CaptureDegradedAt = &now
	logging.Warn(logCtx, "finalize: total deadline exceeded; checkpoints left with provisional transcripts",
		slog.String("session_id", state.SessionID),
		slog.Int("unfinalized_count", unfinalized),
	)
}

// filesChangedInCommit returns the set of files changed in a commit using git diff-tree.
// Uses the git CLI for faster performance vs go-git tree walks (lower constant factors).
// Falls back to go-git tree walk if git diff-tree fails, since an empty result would
// break downstream condensation and carry-forward logic.
func filesChangedInCommit(ctx context.Context, repoDir string, commit *object.Commit, headTree, parentTree *object.Tree) map[string]struct{} {
	var parentHash string
	if commit.NumParents() > 0 {
package strategy

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// ManualCommitStrategy implements the manual-commit strategy for session management.
// It stores checkpoints on shadow branches and condenses session logs to a
// permanent sessions branch when the user commits.
type ManualCommitStrategy struct {
	// stateStore manages session state files in .git/entire-sessions/
	stateStore *session.StateStore
	// stateStoreOnce ensures thread-safe lazy initialization
	stateStoreOnce sync.Once
	// stateStoreErr captures any error during initialization
	stateStoreErr error

	// blobFetcher, when set, is passed to the checkpoint store to enable
	// on-demand blob fetching after treeless fetches. Set via SetBlobFetcher.
	blobFetcher checkpoint.BlobFetchFunc

	// blobFetchBudget bounds one blob fetch on a git-hook path. Zero means
	// remote.WriteProbeFetchBudget. Per-instance rather than a package var so
	// tests can shorten it without mutating process-global state, which
	// t.Parallel() makes a data race (CLAUDE.md: "Tests that modify
	// process-global state cannot be parallelized").
	blobFetchBudget time.Duration

	// turnCheckpointFinalizeBudget bounds the whole turn-finalize pass. Zero
	// means the production default.
	turnCheckpointFinalizeBudget time.Duration

	// checkpointRefFetcher overrides the hook ref fetcher in tests. Production
	// uses remote.HookCheckpointRefFetcher.
	checkpointRefFetcher checkpoint.RefFetchFunc
}

const (
	standardTurnCheckpointFinalizeBudget    = 20 * time.Second
	constrainedTurnCheckpointFinalizeBudget = 5 * time.Second
)

// getStateStore returns the session state store, initializing it lazily if needed.
// Thread-safe via sync.Once.
func (s *ManualCommitStrategy) getStateStore(_ context.Context) (*session.StateStore, error) {
	s.stateStoreOnce.Do(func() {
		store, err := session.NewStateStore(context.Background()) //nolint:contextcheck // sync.Once must use background context to avoid caching errors from a cancelled caller context
		if err != nil {
			s.stateStoreErr = fmt.Errorf("failed to create state store: %w", err)
			return
		}
		s.stateStore = store
	})
	return s.stateStore, s.stateStoreErr
}

func (s *ManualCommitStrategy) getCheckpointStores(ctx context.Context, repo *git.Repository) (*checkpoint.Stores, error) {
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: s.blobFetcher, ReadRemotes: CheckpointReadRemotes(ctx)})
	if err != nil {
		return nil, fmt.Errorf("open checkpoint store: %w", err)
	}
	return stores, nil
}

// getPersistentStore returns a store bound to the resolved committed-metadata
// topology. Writes target refs.Primary; reads target refs.Read. The strategy's
// blob fetcher is wired in so reads can fetch blobs on demand after a treeless
// fetch.
func (s *ManualCommitStrategy) getPersistentStore(ctx context.Context, repo *git.Repository) (checkpoint.PersistentStore, error) {
	stores, err := s.getCheckpointStores(ctx, repo)
	if err != nil {
		return nil, err
	}
	return stores.Persistent, nil
}

// getEphemeralStore returns the git-backed shadow-branch store with the
// strategy's blob fetcher wired in.
func (s *ManualCommitStrategy) getEphemeralStore(ctx context.Context, repo *git.Repository) (checkpoint.EphemeralStore, error) {
	stores, err := s.getCheckpointStores(ctx, repo)
	if err != nil {
		return nil, err
	}
	return stores.Ephemeral(), nil
}

// NewManualCommitStrategy creates a new manual-commit strategy instance.
func NewManualCommitStrategy() *ManualCommitStrategy {
	return &ManualCommitStrategy{}
}

// SetBlobFetcher configures on-demand blob fetching for the checkpoint store.
// Must be called before the first checkpoint store access (e.g., before RestoreLogsOnly).
func (s *ManualCommitStrategy) SetBlobFetcher(f checkpoint.BlobFetchFunc) {
	s.blobFetcher = f
}

// HasBlobFetcher reports whether a blob fetcher is configured.
// Used in tests to verify the strategy is properly wired for treeless fetch support.
func (s *ManualCommitStrategy) HasBlobFetcher() bool {
	return s.blobFetcher != nil
}

// hookCheckpointStoreOptions is the store envelope for a git-hook read: the
// bounded ref probe, the bounded blob fetch, and the read-candidate chain. The
// two bounds live together because a hook that has one and not the other still
// fails — a ref fetcher with no blob fetcher resolves the checkpoint's ref and
// then reads its filtered-out metadata.json as absent, reporting a checkpoint
// that exists as missing.
func (s *ManualCommitStrategy) hookCheckpointStoreOptions(ctx context.Context) checkpoint.OpenOptions {
	refFetcher := s.checkpointRefFetcher
	if refFetcher == nil {
		refFetcher = remote.HookCheckpointRefFetcher()
	}
	return checkpoint.OpenOptions{
		RefFetcher:  refFetcher,
		BlobFetcher: s.hookBlobFetcher(),
		ReadRemotes: CheckpointReadRemotes(ctx),
	}
}

// hookBlobFetcher returns the strategy's blob fetcher bounded for git-hook
// contexts: the write-probe budget over the whole call plus BatchMode SSH, the
// same envelope remote.HookCheckpointRefFetcher puts around the ref probe those
// hooks already run. Reads there must not inherit the interactive read chain's
// minutes while a user's git command waits on the hook.
//
// It fires only when a checkpoint blob is genuinely absent from the local
// object store, which on a full clone never happens — the cost lands on
// partial clones, where the alternative is not "no network" but a checkpoint
// read that reports the checkpoint missing.
//
// The returned fetcher also memoizes budget exhaustion for its own lifetime
// (one hook invocation), which is the blob-side counterpart of
// gitRefsStore.fetchFailure. The ref memo is consulted only in
// resolveRefMaybeFetch, so it does not cover blob reads: those go through
// NewFetchingTree, which holds no memo. Without one, finalizeAllTurnCheckpoints
// looping state.TurnCheckpointIDs against a single store paid
// WriteProbeFetchBudget PER CHECKPOINT on a dead network — and FetchingTree.File
// fetches one hash at a time, so a read touching several missing blobs paid it
// several times. Nothing bounds the total: newGitHookContext adds no deadline,
// and an agent kills the hook long before the loop ends.
//
// Only budget exhaustion is memoized, deliberately. It is the dead-network
// signature and the only failure expensive enough to be worth not repeating; a
// fast error is cheap to retry and may be one blob's genuine remote absence,
// which must not stop the next blob from being fetched. As in the ref memo, a
// cancellation originating from the CALLER says nothing about the remote and is
// never memoized.
func (s *ManualCommitStrategy) hookBlobFetcher() checkpoint.BlobFetchFunc {
	if s.blobFetcher == nil {
		return nil
	}
	var (
		mu        sync.Mutex
		exhausted error
	)
	return func(ctx context.Context, hashes []plumbing.Hash) error {
		// The lock covers the read and is then released — deliberately not held
		// across the check and fetch below. Two things forbid widening it: the
		// fetch is a bounded network call, and the memo write further down
		// re-acquires this same non-reentrant mutex, so holding it here
		// deadlocks. That leaves a check-then-act window where two concurrent
		// first-callers would both fetch, which is acceptable: every caller on
		// these paths is sequential (finalizeAllTurnCheckpoints loops one
		// checkpoint at a time; FetchingTree.File and PreFetch are sequential
		// within a read), and if it were ever reached the cost is one duplicate
		// fetch, not a wrong answer.
		mu.Lock()
		prior := exhausted
		mu.Unlock()
		if prior != nil {
			return prior
		}

		budget := s.blobFetchBudget
		if budget == 0 {
			budget = remote.WriteProbeFetchBudget
		}
		fetchCtx, cancel := context.WithTimeout(remote.WithNonInteractiveSSH(ctx), budget)
		defer cancel()
		err := s.blobFetcher(fetchCtx, hashes)
		if err != nil && ctx.Err() == nil && errors.Is(fetchCtx.Err(), context.DeadlineExceeded) {
			mu.Lock()
			if exhausted == nil {
				exhausted = err
			}
			mu.Unlock()
		}
		return err
	}
}

// ValidateRepository validates that the repository is suitable for this strategy.
func (s *ManualCommitStrategy) ValidateRepository() error {
	repo, err := OpenRepository(context.Background())
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}
	defer repo.Close()

	_, err = repo.Worktree()
	if err != nil {
		return fmt.Errorf("failed to access worktree: %w", err)
	}

	return nil
}

