   275	func (s *gitRefsStore) backfillTranscript(ctx context.Context, opts UpdateOptions) error {
   276		if err := ctx.Err(); err != nil {
   277			return err //nolint:wrapcheck // Propagating context cancellation
   278		}
   279		if opts.CheckpointID.IsEmpty() {
   280			return errors.New("invalid update options: checkpoint ID is required")
   281		}
   282	
   283		parentHash, existing, err := s.refBaseForBackfill(ctx, opts.CheckpointID)
   284		if err != nil {
   285			return err
   286		}
   287	
   288		// applyTranscriptBackfill returns ErrCheckpointNotFound when the ref has no
   289		// root summary yet (existing == nil → empty entries), matching the git-branch
   290		// store's behavior for backfilling an unknown checkpoint.
   291		checkpointSubtree, err := s.applyTranscriptBackfill(ctx, opts, existing, "")
   292		if err != nil {
   293			return err
   294		}
   295	
   296		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
   297		commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
   298		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
   299		if err != nil {
   300			return err
   301		}
   302		return s.setRef(ctx, opts.CheckpointID, commitHash)
   303	}
