   305	func (s *gitRefsStore) backfillSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   380	// resolveRefMaybeFetch resolves a checkpoint ref, fetching it from the remote
   381	// once when it is missing locally and a ref fetcher is configured (the
   382	// checkpoint may have been written on another machine). It distinguishes a
   383	// genuinely absent ref (returns a plumbing.ErrReferenceNotFound-wrapped error,
   384	// which callers map to ErrCheckpointNotFound) from a real failure — an IO error,
   385	// or a fetch that failed for network/context reasons — which is returned as-is
   386	// so it is not silently swallowed as "checkpoint not found".
   387	func (s *gitRefsStore) resolveRefMaybeFetch(ctx context.Context, cid id.CheckpointID) (*plumbing.Reference, error) {
   388		refName, err := RefName(cid)
   389		if err != nil {
   390			return nil, err
   391		}
   392		ref, err := s.repo.Reference(refName, true)
   393		if err == nil {
   394			return ref, nil
   395		}
   396		if !errors.Is(err, plumbing.ErrReferenceNotFound) {
   397			return nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
   398		}
   399		if s.refFetcher == nil {
   400			return nil, err //nolint:wrapcheck // genuinely absent; caller maps ErrReferenceNotFound to ErrCheckpointNotFound
   401		}
   402		s.fetchFailureMu.Lock()
   403		priorFailure := s.fetchFailure
   404		s.fetchFailureMu.Unlock()
   405		if priorFailure != nil {
   406			// Note the cause may name a DIFFERENT ref — it is the first failure
   407			// of this operation, remembered so the outage is paid once.
   408			return nil, fmt.Errorf("fetch checkpoint ref %s: skipped, an earlier checkpoint-ref fetch already failed in this operation: %w", refName, priorFailure)
   409		}
   410		if fetchErr := s.refFetcher(ctx, refName); fetchErr != nil {
   411			if errors.Is(fetchErr, plumbing.ErrReferenceNotFound) {
   412				// The fetcher probed the remote and it genuinely lacks this ref
   413				// (remote.FetchCheckpointRef's absence signal) — absence, not a
   414				// failure, and per-ref, so it is not memoized.
   415				logging.Debug(ctx, "git-refs: remote has no such checkpoint ref",
   416					slog.String("ref", refName.String()))
   417				return nil, plumbing.ErrReferenceNotFound
   418			}
   419			// Memoize only network verdicts: a cancellation originating from the
   420			// CALLER's context says nothing about the remote and must not poison
   421			// later fetches on this store.
   422			if ctx.Err() == nil {
   423				s.fetchFailureMu.Lock()
   424				if s.fetchFailure == nil {
   425					s.fetchFailure = fetchErr
   426				}
   427				s.fetchFailureMu.Unlock()
   428			}
   429			logging.Debug(ctx, "git-refs: on-demand checkpoint ref fetch failed",
   430				slog.String("ref", refName.String()), slog.String("error", fetchErr.Error()))
   431			return nil, fmt.Errorf("fetch checkpoint ref %s: %w", refName, fetchErr)
   432		}
   433		// Re-resolve after a successful fetch. ErrReferenceNotFound here means the
   434		// remote genuinely has no such checkpoint; anything else is a real error.
   435		ref, err = s.repo.Reference(refName, true)
   436		if err != nil {
   437			return nil, err //nolint:wrapcheck // ErrReferenceNotFound (absent) or a real error; caller distinguishes via errors.Is
   438		}
   439		return ref, nil
   440	}
