const cmds = [
 ["race_focused", "go test -race ./cmd/entire/cli/strategy -run '^(TestTurnCheckpointFinalizeBudgetForAgent|TestFinalizeAllTurnCheckpointsStopsAtTotalBudget|TestHandleTurnEnd_PartialFailure|TestFinalizeAllTurnCheckpoints_ScannerDegraded)$' -count=5"],
 ["status_test_names", "rg -n '^func Test.*Status' cmd/entire/cli/status_test.go | head -120"],
 ["branch_compare", "git diff --stat upstream/main...HEAD && git diff --check upstream/main...HEAD && git merge-tree $(git merge-base upstream/main HEAD) upstream/main HEAD | rg -n '^<<<<<<<|^=======$|^>>>>>>>'"],
 ["committed_files_full_sizes", "wc -l cmd/entire/cli/session/state.go cmd/entire/cli/status.go cmd/entire/cli/strategy/manual_commit.go cmd/entire/cli/strategy/manual_commit_finalize_deadline_test.go cmd/entire/cli/strategy/manual_commit_hooks.go cmd/entire/cli/strategy/phase_postcommit_test.go"]
];
const results=await Promise.all(cmds.map(async ([name,cmd])=>{const r=await tools.exec_command({cmd,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-turn-checkpoint-finalize-deadline-2148",yield_time_ms:30000,max_output_tokens:30000});return{name,code:r.exit_code,output:r.output};}));
for(const r of results) text(`=== ${r.name} (exit ${r.code}) ===\n${r.output}`);

